@@ -0,0 +1,51 @@
+import 'package:flutter/material.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:integration_test/integration_test.dart';
+
+import '../test/schedule_search_test.dart'
+    show PendingSearchRepository, openScheduleSearch, searchResult;
+
+/// Runs the real scheduler and platform keyboard with delayed synthetic results.
+void main() {
+  final binding = IntegrationTestWidgetsFlutterBinding.ensureInitialized();
+  for (final brightness in Brightness.values) {
+    testWidgets('scheduler search keeps native keyboard (${brightness.name})', (
+      tester,
+    ) async {
+      final repository = PendingSearchRepository();
+      await openScheduleSearch(tester, repository, brightness: brightness);
+      await tester.tap(find.byType(TextField));
+      await tester.enterText(find.byType(TextField), '高');
+      await tester.pump(const Duration(milliseconds: 600));
+      await tester.pump();
+      expect(repository.queries, ['高']);
+      expect(find.byType(TextField), findsOneWidget);
+      final editable = tester.widget<EditableText>(find.byType(EditableText));
+      expect(editable.controller.text, '高');
+      expect(editable.focusNode.hasFocus, isTrue);
+      expect(
+        tester.view.viewInsets.bottom,
+        greaterThan(0),
+        reason: 'the native software keyboard remains visible',
+      );
+
+      await tester.enterText(find.byType(TextField), '高等数学');
+      await tester.pump(const Duration(milliseconds: 600));
+      await tester.pump();
+      expect(repository.queries, ['高', '高等数学']);
+      repository.requests.last.complete(searchResult('高等数学（演示结果）'));
+      repository.requests.first.complete(searchResult('高（过期结果）'));
+      await tester.pumpAndSettle();
+      expect(find.text('高等数学（演示结果）'), findsOneWidget);
+      expect(find.text('高（过期结果）'), findsNothing);
+      expect(editable.controller.text, '高等数学');
+      expect(editable.focusNode.hasFocus, isTrue);
+      expect(tester.view.viewInsets.bottom, greaterThan(0));
+      if (const bool.fromEnvironment('YOURTJ_TEST_SCREENSHOTS')) {
+        await binding.takeScreenshot('schedule-search-${brightness.name}');
+      }
+      await tester.pumpWidget(const SizedBox());
+      await tester.pumpAndSettle();
+    });
+  }
+}

diff --git a/apps/mobile/packages/forum_app/integration_test/storage_bootstrap_test.dart b/apps/mobile/packages/forum_app/integration_test/storage_bootstrap_test.dart
new file mode 100644
index 000000000..b96815945
--- /dev/null
+++ b/apps/mobile/packages/forum_app/integration_test/storage_bootstrap_test.dart
@@ -0,0 +1,89 @@
+import 'dart:io';
+
+import 'package:flutter/services.dart';
+import 'package:flutter_riverpod/flutter_riverpod.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:integration_test/integration_test.dart';
+import 'package:path_provider/path_provider.dart';
+import 'package:shared_preferences/shared_preferences.dart';
+
+import 'package:forum_app/src/app_config.dart';
+import 'package:forum_app/src/storage/private_database.dart';
+import 'package:forum_app/src/storage/storage_gate.dart';
+import 'package:forum_app/src/storage/storage_providers.dart';
+
+/// Run on an isolated simulator with the real dev preview dart-defines. This
+/// exercises native backup exclusion, Keychain and encrypted SQLite without
+/// contacting a server or substituting storage providers.
+void main() {
+  IntegrationTestWidgetsFlutterBinding.ensureInitialized();
+
+  testWidgets('dev storage startup and retry preserve production files', (
+    tester,
+  ) async {
+    expect(Platform.isIOS, isTrue);
+    AppConfig.validate();
+    expect(AppConfig.isDev, isTrue);
+    SharedPreferences.setPrefix('flutter.dev.');
+    final support = await getApplicationSupportDirectory();
+    final production = Directory.fromUri(
+      support.uri.resolve('yourtj_private/'),
+    );
+    await production.create(recursive: true);
+    final sentinel = File.fromUri(
+      production.uri.resolve(
+        'storage-bootstrap-test-${DateTime.now().microsecondsSinceEpoch}',
+      ),
+    );
+    await sentinel.writeAsString(
+      'preserve existing production data',
+      flush: true,
+    );
+    addTearDown(sentinel.delete);
+    await const MethodChannel(
+      'yourtj/storage',
+    ).invokeMethod<void>('excludeFromBackup', {'path': production.path});
+
+    final container = ProviderContainer();
+    addTearDown(container.dispose);
+    for (var attempt = 0; attempt < 2; attempt++) {
+      if (attempt > 0) container.invalidate(storageBootstrapProvider);
+      await container.read(storageBootstrapProvider.future);
+      expect(container.read(storageReadyProvider), isTrue);
+      expect(
+        (await privateStorageDirectory()).path,
+        Directory.fromUri(support.uri.resolve('yourtj_private_dev/')).path,
+      );
+      expect(
+        await sentinel.readAsString(),
+        'preserve existing production data',
+      );
+    }
+  });
+
+  testWidgets('native backup exclusion rejects unmanaged paths', (
+    tester,
+  ) async {
+    final support = await getApplicationSupportDirectory();
+    for (final relative in [
+      '.',
+      'yourtj_private_dev/unrelated',
+      'yourtj_private_dev_other',
+      '../yourtj_private_dev',
+    ]) {
+      await expectLater(
+        const MethodChannel('yourtj/storage').invokeMethod<void>(
+          'excludeFromBackup',
+          {'path': Directory.fromUri(support.uri.resolve(relative)).path},
+        ),
+        throwsA(
+          isA<PlatformException>().having(
+            (error) => error.code,
+            'code',
+            'invalid_path',
+          ),
+        ),
+      );
+    }
+  });
+}

