+Set<String> mislabeledLinkTargets(String markdown) {
+  final Set<String> targets = <String>{};
+  for (final UrlLabeledLink link in urlLabeledMarkdownLinks(markdown)) {
+    if (_isMislabeledLink(link)) targets.add(link.href);
+  }
