+    if (selectTab == null) {
+      widget.onChanged(index);
+    } else {
+      selectTab(index);
+    }
+  }
+
+  @override
+  void dispose() {
+    _swipeProgressNotifier?.removeListener(_onSwipeProgressChanged);
+    _controller.dispose();
+    super.dispose();
+  }
+
+  String _iconFor(String key) => switch (key) {
+    'timeline' => 'activity',
+    'topics' => 'file-text',
+    'replies' => 'message-circle',
+    'likes' => 'heart',
+    'bookmarks' => 'bookmark',
+    'badges' => 'award',
+    'following' => 'user-round-check',
+    'followers' => 'users-round',
+    _ => 'circle-user-round',
+  };
+
+  /// The tab icon, with a lock badge on its corner for restricted sections.
+  /// The badge overlays the glyph, so tab widths and label motion stay as is.
+  Widget _glyph(BuildContext context, String key, Color? color) {
