+              shape: BoxShape.circle,
+            ),
+            child: Padding(
+              padding: const EdgeInsets.all(1.5),
+              child: GfSymbol('lock-filled', size: 10, color: color),
+            ),
+          ),
+        ),
+      ],
+    );
+  }
+
+  String _describe(TabItemPayload tab) {
