+                  '春天',
+                  '数学',
+                  '微风',
+                  '海棠',
+                  '山川',
+                  '北斗',
+                ],
+              };
+              stored[key] = batch;
+              (state['batches'] as List).add(batch);
+              state['remaining'] = (state['remaining'] as int) - 1;
+            }
+            if (failDraw) {
+              failDraw = false;
+              h.reject(
+                DioException(
+                  requestOptions: o,
+                  type: DioExceptionType.connectionError,
+                ),
+              );
+              return;
+            }
+            result = stored[key];
+          } else if (o.path.endsWith('/confirm')) {
+            confirms++;
+            await confirmWait?.future;
+            if (failConfirm) {
+              h.reject(
+                DioException(
+                  requestOptions: o,
+                  type: DioExceptionType.connectionError,
+                ),
+              );
+              return;
+            }
+            result = {
+              'kind': 'persona',
+              'publicUid': 'a' * 32,
+              'name': '星辰',
+              'avatarUrl': '',
+              'profileUrl': '/a/${'a' * 32}',
