+              context,
+              selection,
+              buttonItems,
+            ) ??
+            AdaptiveTextSelectionToolbar.buttonItems(
+              anchors: selection.contextMenuAnchors,
+              buttonItems: buttonItems,
+            );
+      },
+      child: _TwemojiSelectionScope(registry: _registry, child: widget.child),
+    ),
