+    'token': token,
+    'topicIds': topicIds,
+    'issuedAt': issuedAt,
+    'expiresAt': expiresAt,
+  };
+}
+
+class FeedSeenPatch {
+  const FeedSeenPatch({required this.proof, required this.seen});
+  final String proof;
+  final Map<String, int> seen;
+  Map<String, dynamic> toJson() => {'proof': proof, 'seen': seen};
