+            ),
+          ),
+          'zh',
+          brightness,
+          campusStatus: const CampusStatus(
+            enabled: true,
+            binding: testBinding,
+            candidate: null,
+          ),
+        );
+        expect(find.byType(ActivationEmailAction), findsNothing);
+        await tester.tap(find.text(l.campusReauthorize));
