+    _fromIndicatorCenterShare = _displayedIndicatorCenterShare;
+    _fromIndicatorWidthShare = _displayedIndicatorWidthShare;
+    if (_disableAnimations) {
+      _controller.value = 1;
+      _tapSelection = false;
+      _controller.duration = _animationDuration;
