+                              '\n${credential.backupEligible ? l10n.settingsPasskeySyncCapable : l10n.settingsPasskeyDeviceBound}'
+                              '${credential.backupEligible && credential.backupState ? ' · ${l10n.settingsPasskeyBackedUp}' : ''}',
+                            ),
