+import 'package:core/core.dart';
+import 'package:flutter/material.dart';
+import 'package:flutter_riverpod/flutter_riverpod.dart';
+import 'package:ui_kit/ui_kit.dart';
+
+import '../../l10n/app_localizations.dart';
+import '../providers.dart';
+import '../server_messages.dart';
+import '../widgets/status_views.dart';
+
+final pushPreferencesProvider = FutureProvider.autoDispose<PushPreferences>((
+  ref,
+) {
+  ref.watch(offlineCacheEpochProvider);
+  return ref.watch(pushRepositoryProvider).preferences();
+});
+
+class PushPreferencesPanel extends ConsumerStatefulWidget {
+  const PushPreferencesPanel({super.key});
+  @override
+  ConsumerState<PushPreferencesPanel> createState() =>
+      _PushPreferencesPanelState();
+}
+
+class _PushPreferencesPanelState extends ConsumerState<PushPreferencesPanel> {
+  bool _saving = false;
+
+  Future<void> _save(String group, bool value) async {
+    if (_saving) return;
+    final epoch = ref.read(offlineCacheEpochProvider);
+    setState(() => _saving = true);
+    try {
+      final repository = await ref.read(pushRepositoryProvider).forSession();
+      if (!mounted || epoch != ref.read(offlineCacheEpochProvider)) return;
+      await repository.updatePreferences({group: value});
+      if (mounted && epoch == ref.read(offlineCacheEpochProvider)) {
+        ref.invalidate(pushPreferencesProvider);
+      }
+    } catch (error) {
+      if (mounted && epoch == ref.read(offlineCacheEpochProvider)) {
+        showGfToast(
+          context,
+          resolveErrorMessage(AppLocalizations.of(context), error),
+          error: true,
+        );
+      }
+    } finally {
+      if (mounted) setState(() => _saving = false);
+    }
+  }
+
+  @override
+  Widget build(BuildContext context) {
+    final l10n = AppLocalizations.of(context);
+    final labels = {
+      'chat': l10n.pushChat,
+      'mentionsAndReplies': l10n.pushMentionsAndReplies,
+      'activity': l10n.pushActivity,
+      'following': l10n.pushFollowing,
+      'system': l10n.pushSystem,
+    };
+    return ref
+        .watch(pushPreferencesProvider)
+        .when(
+          loading: () => const Padding(
+            padding: EdgeInsets.all(16),
+            child: GfLoadingIndicator(small: true),
+          ),
+          error: (error, _) => GfErrorRetry(
+            message: resolveErrorMessage(l10n, error),
+            onRetry: () => ref.invalidate(pushPreferencesProvider),
+          ),
+          data: (preferences) => AbsorbPointer(
+            absorbing: _saving,
+            child: Column(
+              children: [
+                for (final entry in preferences.toJson().entries) ...[
+                  const GfDivider(),
+                  GfSwitchRow(
+                    title: labels[entry.key]!,
+                    value: entry.value,
+                    onChanged: (value) => _save(entry.key, value),
+                  ),
+                ],
+              ],
+            ),
+          ),
+        );
+  }
+}

diff --git a/apps/mobile/packages/forum_app/lib/src/push/push_route.dart b/apps/mobile/packages/forum_app/lib/src/push/push_route.dart
new file mode 100644
index 000000000..e7978ccfc
--- /dev/null
+++ b/apps/mobile/packages/forum_app/lib/src/push/push_route.dart
@@ -0,0 +1,49 @@
+/// Notifications may navigate only to notification-owned in-app routes.
+String? pushRoute(String? value) {
+  if (value == null) return null;
+  final uri = Uri.tryParse(value);
+  if (uri == null || uri.hasScheme || uri.hasAuthority || uri.hasFragment) {
+    return null;
+  }
+  final rawPath = value
+      .split('?')
+      .first
+      .replaceAll(RegExp('%2e', caseSensitive: false), '.');
+  if (RegExp(r'(^|/)\.\.?(/|$)').hasMatch(rawPath)) return null;
+  bool positive(String? value) =>
+      value != null && RegExp(r'^[1-9][0-9]*$').hasMatch(value);
+  final allowed = <String>{'recipientId'};
+  if (RegExp(r'^/p/[1-9][0-9]*$').hasMatch(uri.path)) {
+    allowed.add('postNo');
+  } else if (uri.path == '/chat') {
+    allowed.add('userId');
+    if (!positive(uri.queryParameters['userId'])) return null;
+  } else if (uri.path.startsWith('/wiki/')) {
+    if (uri.pathSegments
+        .skip(1)
+        .any(
+          (part) =>
+              part.isEmpty ||
+              part == '.' ||
+              part == '..' ||
+              part.contains('/') ||
+              part.contains('\\') ||
+              part.runes.any((char) => char < 32),
+        )) {
+      return null;
+    }
+  } else if (!RegExp(r'^/u/[1-9][0-9]*$').hasMatch(uri.path) &&
+      uri.path != '/notifications' &&
+      uri.path != '/my-content') {
+    return null;
+  }
+  if (uri.queryParametersAll.entries.any(
+    (entry) =>
+        !allowed.contains(entry.key) ||
+        entry.value.length != 1 ||
+        !positive(entry.value.single),
+  )) {
+    return null;
+  }
+  return value;
+}

