+    testWidgets(
+      'name selection confirms explicitly and fits at $width with large text',
+      (tester) async {
+        tester.view.physicalSize = Size(width, 1000);
+        tester.view.devicePixelRatio = 1;
+        addTearDown(tester.view.resetPhysicalSize);
+        addTearDown(tester.view.resetDevicePixelRatio);
+        var confirms = 0;
+        final dio = Dio();
+        dio.interceptors.add(
+          InterceptorsWrapper(
+            onRequest: (options, handler) {
+              if (options.path.endsWith('/confirm')) confirms++;
+              handler.resolve(
+                Response(
+                  requestOptions: options,
+                  statusCode: 200,
+                  data: {
+                    'code': 0,
+                    'result': {
+                      'kind': 'persona',
+                      'publicUid': 'a' * 32,
+                      'name': long,
+                      'avatarUrl': '',
+                      'profileUrl': '/a/${'a' * 32}',
+                    },
+                  },
+                ),
+              );
+            },
+          ),
+        );
+        final client = GfApiClient(
+          dio: dio,
+          tokenStorage: MemoryTokenStorage(),
+          baseUrl: 'http://fake.local',
+        );
+        final state = AnonymousIdentityState.fromJson({
+          'persona': null,
+          'day': '2026-10-06',
+          'remaining': 9,
+          'resetsAt': '2026-10-06T16:00:00Z',
+          'nameSelectedAt': null,
+          'nameChangeAvailableAt': null,
+          'disabled': false,
+          'governanceDisabled': false,
+          'lexiconVersion': 'THUOCL-a30ce79',
+          'batches': [
+            {
+              'id': 'b' * 32,
+              'day': '2026-10-06',
+              'createdAt': '2026-10-06T00:00:00Z',
+              'expiresAt': '2026-10-06T16:00:00Z',
+              'words': [
+                long,
+                'C++',
+                '人',
+                '数学',
+                '大学',
+                '上海',
+                '同学',
+                '春天',
+                '星辰',
+                '通济',
+              ],
+            },
+          ],
+        });
+        await tester.pumpWidget(
+          ProviderScope(
+            overrides: [
+              apiClientProvider.overrideWithValue(client),
+              anonymousIdentityProvider.overrideWith((ref) async => state),
+            ],
+            child: MaterialApp(
+              locale: const Locale('zh'),
+              localizationsDelegates: AppLocalizations.localizationsDelegates,
+              supportedLocales: AppLocalizations.supportedLocales,
+              theme: gfThemeData(Brightness.light),
+              builder: (context, child) => MediaQuery(
+                data: MediaQuery.of(
+                  context,
+                ).copyWith(textScaler: const TextScaler.linear(2)),
+                child: child!,
+              ),
+              home: const AnonymousIdentityPage(),
+            ),
+          ),
+        );
+        await tester.pumpAndSettle();
+        final candidate = find.text(long);
+        await tester.ensureVisible(candidate);
+        await tester.tap(candidate);
+        await tester.pumpAndSettle();
+        expect(confirms, 0);
+        // The name-tag preview shows the picked slip before confirmation.
+        await tester.drag(find.byType(ListView).first, const Offset(0, 4000));
+        await tester.pumpAndSettle();
+        expect(find.text('别人会这样看到你'), findsOneWidget);
+        expect(find.text('从下面挑一个花名'), findsNothing);
+        expect(find.byType(AlertDialog), findsNothing);
+        expect(tester.takeException(), isNull);
+        final confirm = find.widgetWithText(GfButton, '使用这个花名');
+        await tester.ensureVisible(confirm);
+        await tester.tap(confirm);
+        await tester.pumpAndSettle();
+        expect(confirms, 1);
+        expect(tester.takeException(), isNull);
+      },
