+  test(
+    'local writing recovery retains a persona and rejects an unknown identity',
+    () {
+      const draft = LocalDraft(
+        key: 'reply-1',
+        title: '',
+        content: '匿名正文',
+        contentType: 0,
+        topicId: 1,
+        categories: [],
+        images: [],
+        updatedAt: 1,
+        kind: DraftKind.reply,
+        identity: 'persona',
