+      expect(LocalDraft.fromJson(draft.toJson()).identity, 'persona');
+      expect(
+        LocalDraft.fromJson({...draft.toJson()}..remove('identity')).identity,
+        'member',
+      );
+      expect(
+        () => LocalDraft.fromJson({...draft.toJson(), 'identity': 'forged'}),
+        throwsFormatException,
+      );
+    },
+  );
