+    appeals.add(reason);
+    item = UserContentItem(
+      id: item.id,
+      contentType: item.contentType,
+      title: item.title,
+      processStatus: 1,
+      revisionId: 70,
+      reviewReason: item.reviewReason,
+      appeal: ModerationAppealOwnerSummary(
