+    final GlobalKey<NestedScrollViewState> nestedKey =
+        GlobalKey<NestedScrollViewState>();
+    addTearDown(() async {
+      await tester.pumpWidget(const SizedBox.shrink());
+      outerController.dispose();
+    });
+
+    await tester.pumpWidget(
+      MaterialApp(
+        home: GfStatusBarScrollToTop(
