+    avatarUrl: json['avatarUrl'] as String? ?? '',
+    actorType: json['actorType'] as String,
+  );
+}

diff --git a/apps/mobile/packages/core/lib/src/gen/moderation_appeal.dart b/apps/mobile/packages/core/lib/src/gen/moderation_appeal.dart
