+      idempotencyKey: 'topic:evt_1',
+    );
+    final post = AgentCreatePostInput(
+      content: 'A reply',
+      replyToPostId: 44,
+      sourceEventId: 'evt_1',
+      idempotencyKey: 'reply:evt_1',
+    );
+
+    expect(topic.toJson(), {
+      'title': 'A useful topic',
+      'content': 'Markdown',
+      'categoryId': [2],
+      'sourceEventId': 'evt_1',
+    });
+    expect(post.toJson(), {
+      'content': 'A reply',
+      'replyToPostId': 44,
+      'sourceEventId': 'evt_1',
+    });
+    expect(AgentAckEventsInput(eventIds: ['evt_1']).toJson(), {
+      'eventIds': ['evt_1'],
+    });
+  });
+}

