diff --git a/apps/mobile/packages/forum_app/test/passkey_availability_test.dart b/apps/mobile/packages/forum_app/test/passkey_availability_test.dart
new file mode 100644
index 000000000..5bd356e87
--- /dev/null
+++ b/apps/mobile/packages/forum_app/test/passkey_availability_test.dart
@@ -0,0 +1,73 @@
+import 'package:flutter/foundation.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:forum_app/src/pages/auth/passkey_availability.dart';
+
+void main() {
+  test('only probes the current supported platform', () async {
+    var webCalls = 0;
+    var androidCalls = 0;
+    var iosCalls = 0;
+    Future<bool> web() async {
+      webCalls++;
+      return true;
+    }
+
+    Future<bool> android() async {
+      androidCalls++;
+      return true;
+    }
+
+    Future<bool> ios() async {
+      iosCalls++;
+      return false;
+    }
+
+    expect(
+      await resolvePasskeyAvailability(
+        isWeb: false,
+        platform: TargetPlatform.android,
+        web: web,
+        android: android,
+        ios: ios,
+      ),
+      isTrue,
+    );
+    expect(androidCalls, 1);
+    expect(webCalls, 0);
+    expect(iosCalls, 0);
+
+    expect(
+      await resolvePasskeyAvailability(
+        isWeb: false,
+        platform: TargetPlatform.iOS,
+        web: web,
+        android: android,
+        ios: ios,
+      ),
+      isFalse,
+    );
+    expect(iosCalls, 1);
+
+    expect(
+      await resolvePasskeyAvailability(
+        isWeb: false,
+        platform: TargetPlatform.linux,
+        web: web,
+        android: android,
+        ios: ios,
+      ),
+      isFalse,
+    );
+    expect(
+      await resolvePasskeyAvailability(
+        isWeb: true,
+        platform: TargetPlatform.linux,
+        web: web,
+        android: android,
+        ios: ios,
+      ),
+      isTrue,
+    );
+    expect(webCalls, 1);
+  });
+}

diff --git a/apps/mobile/packages/forum_app/test/passkey_error_message_test.dart b/apps/mobile/packages/forum_app/test/passkey_error_message_test.dart
new file mode 100644
index 000000000..2b4e1027d
--- /dev/null
+++ b/apps/mobile/packages/forum_app/test/passkey_error_message_test.dart
@@ -0,0 +1,54 @@
+import 'package:flutter/widgets.dart';
+import 'package:flutter_test/flutter_test.dart';
+import 'package:forum_app/l10n/app_localizations.dart';
+import 'package:forum_app/src/pages/auth/passkey_error_message.dart';
+import 'package:passkeys/exceptions.dart';
+
+void main() {
+  late AppLocalizations l10n;
+
+  setUpAll(() async {
+    l10n = await AppLocalizations.delegate.load(const Locale('en'));
+  });
+
+  test('maps user cancellation and missing credentials to a safe retry hint', () {
+    expect(
+      resolvePasskeyErrorMessage(
+        l10n,
+        PasskeyAuthCancelledException(),
+        fallback: 'generic',
+      ),
+      l10n.authPasskeyCancelled,
+    );
+    expect(
+      resolvePasskeyErrorMessage(
+        l10n,
+        NoCredentialsAvailableException(),
+        fallback: 'generic',
+      ),
+      l10n.authPasskeyCancelled,
+    );
+  });
+
+  test('maps unsupported providers to the existing sign-in fallback', () {
+    expect(
+      resolvePasskeyErrorMessage(
+        l10n,
+        NoCreateOptionException('provider details'),
+        fallback: 'generic',
+      ),
+      l10n.authPasskeyUnavailable,
+    );
+  });
+
+  test('does not expose native domain association diagnostics', () {
+    expect(
+      resolvePasskeyErrorMessage(
+        l10n,
+        DomainNotAssociatedException('internal association details'),
+        fallback: 'generic',
+      ),
+      'generic',
+    );
+  });
+}

