+    // so loading, decode failure and load failure can never leak a colour ring.
+    return SizedBox(
+      width: size,
+      height: size,
+      child: Stack(
+        clipBehavior: Clip.none,
+        children: [
+          child,
+          Positioned(
+            left: -(edge - size) / 2,
+            top: -(edge - size) / 2,
+            width: edge,
+            height: edge,
+            child: IgnorePointer(
+              child: uri.path.endsWith('.svg')
+                  ? GfNetworkSvg(assetUrl, fallback: const SizedBox.shrink())
