diff --git a/apps/mobile/packages/ui_kit/lib/src/components/surfaces/gf_status_bar_scroll_to_top.dart b/apps/mobile/packages/ui_kit/lib/src/components/surfaces/gf_status_bar_scroll_to_top.dart
