+        for (var cursor = index; cursor < unsupportedEnd; cursor++) {
+          plain.writeCharCode(codepoints[cursor]);
+        }
+        index = unsupportedEnd;
+        continue;
+      }
+      if (joinedEnd > bestEnd) {
